hv=smplus('P43','Hidden valley displayed nv3 charge benchmark',[field('N^c',kind='F',copies=3),field('U',kind='F'),field('Ubar',kind='F'),field('C',kind='F'),field('Cbar',kind='F'),field('phi')])
