record('P43',[claim('P43','table','Simple v-Model, TableI','three right-','GSM x SU(nv) x U1chi; two hidden flavours U,Ubar,C,Cbar fundamental/anti-fundamental, three neutrino singlets and complex phi. TableI is in common left-chiral SM q,ubar,dbar,L,eplus convention: chi charges -1/5,-1/5,3/5,3/5,-1/5,N=-1,H=2/5,phi=2. Table neutrino N is the left-chiral charge-conjugate coordinate, despite prose right-handed species naming: Majorana coupling NNphi is neutral. Retain table charges, do not conjugate this already conjugate coordinate twice.',basis='source_table_and_common_chiral_coordinate_derivation'),claim('P43','benchmark','After Eq.(3), benchmark statement','simple case nv = 3, k = 0','Source explicitly specializes nv=3,k=0,qplus=-2; qminus=0 from qplus+qminus=-2. Uchi charges U=-2,Ubar=0,C=+2,Cbar=0. Joint full spectrum scales chi by5 and ordinary Y by6. One-/two-light-flavour mass regimes share microscopic matter.'),claim('P43','families','TableI, kinetic mixing and Other Models','particles X, X̄ charged under both color','Generic nv,qplus and kinetic-basis mixing are explicit families. Coloured X/Xbar alternatives specify colour triplet/octet and valley adjoint/fundamental possibilities, not a full fixed electroweak, Lorentz or multiplicity assignment.')],
 'Complete Simple v-Model table and numerical benchmark plus Other Models coloured-X alternatives.',candidates=[candidate('valley-benchmark',hv,'hidden-valley-chi-two-flavor',['table','benchmark','baseline'])],models=[{'target_entry_ids':['hidden-valley-chi-two-flavor','hidden-valley-colored-x-framework','hidden-valley-x-adjoint-prompt','hidden-valley-x-adjoint-stable','hidden-valley-x-fundamental-stable'],'status':'partial','value_status':'explicit_symbolic_family_or_source_unspecified_mediator_representation','reason':'Generic nv/charges/mixing not replaced by the ready numerical benchmark. Coloured-X source does not fix spin, weak representation, hypercharge or copy count. No invented full spectrum.'}])
